14	// STEP_ORDER now name exactly those four steps. The ADR-0056 producer/
15	// consumer run-phase partition (PRODUCER_STEPS/CONSUMER_STEPS,
16	// stepsForPhase/stepOrderForPhase/stepInPhase, --phase/--as-of) and the
17	// ADR-0050 cross-run note-relation config (resolveMemoryRelationsConfig,
18	// the divergence/supersession proximity-window and textual-judge defaults)
19	// are deleted with it: both existed only to serve the note system.
20	export type StepName = 'retrieve' | 'analyze' | 'decide' | 'review';
21	
22	export const STEP_ORDER: StepName[] = ['retrieve', 'analyze', 'decide', 'review'];
23	
24	export function getStepConfig(config: PipelineConfig, stepName: StepName): StepConfig {
25	  const step = config.steps[stepName];
26	  if (!step) throw new Error(`Unknown step: ${stepName}. Valid steps: ${STEP_ORDER.join(', ')}`);
27	  return step;
28	}
